DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.department_scorecards(date)'::regprocedure) INTO f; f:=replace(f,'LEFT JOIN (SELECT assignee_id,due_date,status,done_at,client_id,launch_id FROM client_tasks UNION ALL SELECT rt.owner_id','LEFT JOIN (SELECT id,assignee_id,due_date,status,done_at,client_id,launch_id FROM client_tasks UNION ALL SELECT rt.id,rt.owner_id'); EXECUTE f; END $$;